      ret <- c(ret,paste("12/31/",currYear,sep=""));
    } else if (currQuarter == 4) {
      ret <- c(ret,paste("3/31/",currYear+1,sep=""));
    }
  }

  ret;
}


How can I make the 'if' statements work on vectors rather than using
